export function dateIso8601(date: Date, timeZone?: string): string {
    if(timeZone) {
        return new Intl.DateTimeFormat('en-CA', { timeZone, year: 'numeric', month: '2-digit', day: '2-digit' }).format(date);
    }
    return dateIso8601(date, 'UTC');
}
